require_once __DIR__ . '/_layout.php';requirePermission('customers.manage');$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$customers=dbFetchAll("SELECT id,first_name,last_name,agency_id FROM customers WHERE agency_id IN ($ph) AND archived_at IS NULL ORDER BY last_name,first_name",$ids);$customerId=(int)($_GET['id']??$_POST['customer_id']??($customers[0]['id']??0));$customer=dbFetchOne('SELECT * FROM customers WHERE id=:id',['id'=>$customerId]);if($customer)requireAgencyAccess($customer['agency_id']);
if(requestMethod()==='POST'){requireCsrfPost();$action=$_POST['action']??'';try{if(!$customer)throw new InvalidArgumentException(t('validation.customer_not_found'));if($action==='driver'){$birth=validDateValue($_POST['date_of_birth']??'');$issue=validDateValue($_POST['licence_issue_date']??'');$expiry=validDateValue($_POST['licence_expires_at']??'');if(!$birth||!$expiry||$expiry<=new DateTimeImmutable('today'))throw new InvalidArgumentException(t('validation.valid_driver_dates'));if($birth->diff(new DateTimeImmutable('today'))->y<appConfig('minimum_driver_age'))throw new DomainException(t('validation.driver_minimum_age'));if($issue&&$issue->diff(new DateTimeImmutable('today'))->m+($issue->diff(new DateTimeImmutable('today'))->y*12)<appConfig('minimum_licence_months'))throw new DomainException(t('validation.driver_licence_seniority'));dbExecute("INSERT INTO additional_drivers(customer_id,first_name,last_name,identity_number,date_of_birth,licence_number,licence_issue_date,licence_expires_at,licence_country,phone,status,created_by)VALUES(:customer,:first,:last,:identity,:birth,:licence,:issue,:expiry,:country,:phone,'active',:user)",['customer'=>$customerId,'first'=>trim((string)$_POST['first_name']),'last'=>trim((string)$_POST['last_name']),'identity'=>trim((string)($_POST['identity_number']??'')),'birth'=>$birth->format('Y-m-d'),'licence'=>trim((string)$_POST['licence_number']),'issue'=>$issue?$issue->format('Y-m-d'):null,'expiry'=>$expiry->format('Y-m-d'),'country'=>strtoupper(substr(trim((string)($_POST['licence_country']??'MA')),0,2)),'phone'=>trim((string)($_POST['phone']??'')),'user'=>currentUserId()]);auditLog('additional_driver.created','additional_driver',db()->lastInsertId(),null,['customer_id'=>$customerId],$customer['agency_id']);flash('success',t('message.driver_added'));}elseif($action==='document'){$stored=storeValidatedDocument($_FILES['document'],'customer_documents');dbExecute('INSERT INTO customer_documents(customer_id,document_type,document_number,issuing_country,issued_at,expires_at,storage_path,original_name,mime_type,file_size,created_by)VALUES(:customer,:type,:number,:country,:issued,:expires,:path,:original,:mime,:size,:user)',['customer'=>$customerId,'type'=>validateChoice($_POST['document_type']??'',['identity','passport','driving_licence','company','other'],'other'),'number'=>trim((string)($_POST['document_number']??'')),'country'=>strtoupper(substr(trim((string)($_POST['issuing_country']??'MA')),0,2)),'issued'=>($_POST['issued_at']??'')?:null,'expires'=>($_POST['expires_at']??'')?:null,'path'=>$stored['path'],'original'=>$stored['original_name'],'mime'=>$stored['mime_type'],'size'=>$stored['size'],'user'=>currentUserId()]);auditLog('customer.document_created','customer_document',db()->lastInsertId(),null,['customer_id'=>$customerId],$customer['agency_id']);flash('success',t('message.customer_document_stored'));} }catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Customer file operation failed');flash('danger',t('message.customer_failed'));}safeRedirect('customer_detail.php?id='.$customerId);}
$drivers=$customer?dbFetchAll('SELECT * FROM additional_drivers WHERE customer_id=:id AND archived_at IS NULL ORDER BY created_at DESC',['id'=>$customerId]):[];$documents=$customer?dbFetchAll('SELECT * FROM customer_documents WHERE customer_id=:id AND archived_at IS NULL ORDER BY expires_at',['id'=>$customerId]):[];$history=$customer?dbFetchAll('SELECT r.reference,r.pickup_at,r.return_at,r.status,r.total_amount,r.currency,v.registration_number FROM reservations r LEFT JOIN vehicles v ON v.id=r.vehicle_id WHERE r.customer_id=:id ORDER BY r.created_at DESC',['id'=>$customerId]):[];$payments=$customer?dbFetchAll('SELECT p.payment_number,p.amount,p.currency,p.paid_at,p.status FROM payments p JOIN reservations r ON r.id=p.reservation_id WHERE r.customer_id=:id ORDER BY p.paid_at DESC',['id'=>$customerId]):[];
backofficeHeader(t('page.customer_detail.title'),'customer_detail.php');?><?php pageHeader('page.customer_detail.title', 'page.customer_detail.description', ['breadcrumbs'=>[['label'=>'nav.customers','href'=>'customers.php'],['label'=>'page.customer_detail.title']],'primary'=>['label'=>'action.add_driver','href'=>'#new-driver']]); ?>
<form class="filters" method="get"><label><?=e(t('field.customer'))?><select name="id" onchange="this.form.submit()"><?php foreach($customers as $c):?><option value="<?=e($c['id'])?>" <?=$customerId===(int)$c['id']?'selected':''?>><?=e($c['last_name'].' '.$c['first_name'])?></option><?php endforeach;?></select></label></form>
<?php if($customer):?><div class="grid"><section class="card" id="new-driver"><h2><?=e(t('section.additional_driver'))?></h2><form method="post"><?=csrfField()?><input type="hidden" name="action" value="driver"><input type="hidden" name="customer_id" value="<?=e($customerId)?>"><label><?=e(t('field.first_name'))?><input name="first_name" required></label><label><?=e(t('field.last_name'))?><input name="last_name" required></label><label><?=e(t('field.identity'))?><input name="identity_number"></label><label><?=e(t('field.date_of_birth'))?><input type="date" name="date_of_birth" required></label><label><?=e(t('field.licence_number'))?><input name="licence_number" required></label><label><?=e(t('field.licence_issue_date'))?><input type="date" name="licence_issue_date"></label><label><?=e(t('field.licence_expiry'))?><input type="date" name="licence_expires_at" required></label><label><?=e(t('field.licence_country'))?><input name="licence_country" value="MA"></label><label><?=e(t('field.phone'))?><input name="phone"></label><button class="btn primary"><?=e(t('action.add_driver'))?></button></form><h2><?=e(t('section.drivers'))?></h2><div class="table-wrap"><table><tr><th><?=e(t('field.name'))?></th><th><?=e(t('field.licence_number'))?></th><th><?=e(t('field.expires'))?></th><th><?=e(t('common.status'))?></th></tr><?php foreach($drivers as $d):?><tr><td><?=e($d['first_name'].' '.$d['last_name'])?></td><td><?=isolatedValue($d['licence_number'],'code-value')?></td><td><?=formattedDate($d['licence_expires_at'])?></td><td><?=statusBadge($d['status'])?></td></tr><?php endforeach;?></table></div></section>
<section class="card"><h2><?=e(t('section.upload_document'))?></h2><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="document"><input type="hidden" name="customer_id" value="<?=e($customerId)?>"><label><?=e(t('field.type'))?><select name="document_type"><?php foreach(['identity','passport','driving_licence','company','other'] as $type):?><option value="<?=e($type)?>"><?=e(t('option.'.$type))?></option><?php endforeach;?></select></label><label><?=e(t('field.number'))?><input name="document_number"></label><label><?=e(t('field.country_code'))?><input name="issuing_country" value="MA"></label><label><?=e(t('field.issued'))?><input type="date" name="issued_at"></label><label><?=e(t('field.expires'))?><input type="date" name="expires_at"></label><label><?=e(t('field.documents'))?><input type="file" name="document" required accept="application/pdf,image/jpeg,image/png,image/webp"></label><button class="btn primary"><?=e(t('action.store_document'))?></button></form><h2><?=e(t('section.documents'))?></h2><div class="table-wrap"><table><tr><th><?=e(t('field.type'))?></th><th><?=e(t('field.number'))?></th><th><?=e(t('field.expires'))?></th></tr><?php foreach($documents as $d):?><tr><td><?=e(t('option.'.$d['document_type']))?></td><td><?=isolatedValue($d['document_number'],'code-value')?></td><td><?=formattedDate($d['expires_at'])?></td></tr><?php endforeach;?></table></div></section></div>
<div class="grid" style="margin-top:1rem"><section class="card"><h2><?=e(t('section.rental_history'))?></h2><div class="table-wrap"><table><tr><th><?=e(t('field.reference'))?></th><th><?=e(t('field.vehicle'))?></th><th><?=e(t('field.period'))?></th><th><?=e(t('common.status'))?></th><th><?=e(t('field.total'))?></th></tr><?php foreach($history as $h):?><tr><td><?=isolatedValue($h['reference'],'reference-value')?></td><td><?=isolatedValue($h['registration_number'],'registration-value')?></td><td><?=formattedDateTime($h['pickup_at'])?><br><?=formattedDateTime($h['return_at'])?></td><td><?=statusBadge($h['status'])?></td><td><?=money($h['total_amount'],$h['currency'])?></td></tr><?php endforeach;?></table></div></section><section class="card"><h2><?=e(t('section.payment_history'))?></h2><div class="table-wrap"><table><tr><th><?=e(t('field.number'))?></th><th><?=e(t('field.date'))?></th><th><?=e(t('field.amount'))?></th><th><?=e(t('common.status'))?></th></tr><?php foreach($payments as $p):?><tr><td><?=isolatedValue($p['payment_number'],'reference-value')?></td><td><?=formattedDateTime($p['paid_at'])?></td><td><?=money($p['amount'],$p['currency'])?></td><td><?=statusBadge($p['status'])?></td></tr><?php endforeach;?></table></div></section></div><?php endif;?><?php backofficeFooter();

